type Engine = ReturnType<typeof useEditor>

export type { ClipDragMode } from '@mcut/editor'
export { NEW_TRACK_LANE_HEIGHT, RULER_HEIGHT, TRACK_HEIGHT } from './timeline-drag-preview'

const SNAP_PX = 8
const DRAG_THRESHOLD_PX = 4

export interface ClipDragBeginOptions {
  mode: ClipDragMode
  ids: ElementId[]
  ignoreIds?: ElementId[]
  duplicateOnDrag: boolean
}

export interface ClipDragPrefs {
  pxPerMs: number
  snapEnabled: boolean
  autoCrossfade: boolean
}

export interface ClipDragDeps {
  engine: Engine
  prefs: () => ClipDragPrefs
  timelineHeaderPx: () => number
  setSnapGuideMs: (ms: number | null) => void
  scrollerRef: React.RefObject<HTMLElement | null>
}

interface ClipDragGesture {
  mode: ClipDragMode
  pointerId: number
  ids: ElementId[]
  bases: Map<ElementId, ClipDragBase>
  anchor: ClipDragBase
  startClientX: number
  startClientY: number
  startScrollLeft: number
  lastClientX: number
  lastClientY: number
  lastAltKey: boolean
  active: boolean
  duplicateOnDrag: boolean
  duplicated: boolean
  createdTrackIds: Track['id'][]
  newTrackId: TrackId
  ignore: ReadonlySet<string>
  targets: SnapTarget[]
  appliedDeltaMs: number
  rollTargetId: ElementId | null
  slipRange: { minMs: number; maxMs: number } | null
  scrollerRect: DOMRect | null
  layer: ClipPreviewLayer | null
  plan: DragPlan | null
  lastValidPlan: DragPlan | null
}

export class ClipDragController {
  constructor(private readonly deps: ClipDragDeps) {}

  private gesture: ClipDragGesture | null = null
  private readonly autoScroll = new EdgeAutoScroll()
  private updateFrame: number | null = null
  private previousBodyUserSelect: string | null = null
  private capture: { element: Element; pointerId: number } | null = null

  begin(event: { clientX: number; clientY: number; pointerId: number }, options: ClipDragBeginOptions): void {
    this.cancel()
    const project = this.deps.engine.project
    const bases = collectClipDragBases(project, options.ids)
    const anchorId = options.ids[0]
    const anchor = anchorId === undefined ? undefined : bases.get(anchorId)
    if (!anchor) return
    const resolved = resolveToolMode(project, options.mode, options.ids)
    this.gesture = {
      mode: resolved.mode,
      pointerId: event.pointerId,
      ids: options.ids,
      bases,
      anchor,
      startClientX: event.clientX,
      startClientY: event.clientY,
      startScrollLeft: this.deps.scrollerRef.current?.scrollLeft ?? 0,
      lastClientX: event.clientX,
      lastClientY: event.clientY,
      lastAltKey: options.duplicateOnDrag,
      active: false,
      duplicateOnDrag: options.duplicateOnDrag,
      duplicated: false,
      createdTrackIds: [],
      newTrackId: createTrackId(),
      ignore: new Set<string>([...options.ids, ...(options.ignoreIds ?? [])]),
      targets: [],
      appliedDeltaMs: 0,
      rollTargetId: resolved.rollTargetId,
      slipRange: resolved.mode === 'slip' ? computeSlipRange(project, options.ids) : null,
      scrollerRect: null,
      layer: null,
      plan: null,
      lastValidPlan: null,
    }
    this.attach()
  }

  get dragging(): boolean {
    return this.gesture?.active ?? false
  }

  dispose = (): void => this.cancel()

  private onPointerMove = (event: PointerEvent) => {
    const gesture = this.gesture
    if (!gesture || event.pointerId !== gesture.pointerId) return
    if ((event.buttons & 1) === 0) {
      this.finish()
      return
    }
    gesture.lastClientX = event.clientX
    gesture.lastClientY = event.clientY
    gesture.lastAltKey = event.altKey
    if (!gesture.active) {
      const travelled = Math.hypot(event.clientX - gesture.startClientX, event.clientY - gesture.startClientY)
      const bodyGesture = gesture.mode === 'move' || gesture.mode === 'slip' || gesture.mode === 'slide'
      if (travelled < (bodyGesture ? DRAG_THRESHOLD_PX : 1)) return
      this.activate(gesture)
    }
    if (this.updateFrame !== null) return
    this.updateFrame = requestAnimationFrame(() => {
      this.updateFrame = null
      this.update()
    })
  }

  private onPointerUp = (event: PointerEvent) => {
    if (this.gesture?.pointerId === event.pointerId) this.finish()
  }

  private onPointerCancel = (event: PointerEvent) => {
    if (this.gesture?.pointerId === event.pointerId) this.cancel()
  }

  private onKeyDown = (event: KeyboardEvent) => {
    if (event.key !== 'Escape' || !this.gesture) return
    event.preventDefault()
    event.stopPropagation()
    this.cancel()
  }

  private onWindowBlur = () => this.cancel()

  private listening: AbortController | null = null

  private attach(): void {
    this.listening = new AbortController()
    const { signal } = this.listening
    window.addEventListener('pointermove', this.onPointerMove, { signal })
    window.addEventListener('pointerup', this.onPointerUp, { signal })
    window.addEventListener('pointercancel', this.onPointerCancel, { signal })
    window.addEventListener('blur', this.onWindowBlur, { signal })
    window.addEventListener('keydown', this.onKeyDown, { signal, capture: true })
  }

  private detach(): void {
    this.listening?.abort()
    this.listening = null
    if (this.capture !== null && this.capture.element.hasPointerCapture(this.capture.pointerId)) {
      this.capture.element.releasePointerCapture(this.capture.pointerId)
    }
    this.capture = null
    this.autoScroll.stop()
    if (this.updateFrame !== null) {
      cancelAnimationFrame(this.updateFrame)
      this.updateFrame = null
    }
    if (this.previousBodyUserSelect !== null) {
      document.body.style.userSelect = this.previousBodyUserSelect
      this.previousBodyUserSelect = null
    }
  }

  private activate(gesture: ClipDragGesture): void {
    const { engine, scrollerRef } = this.deps
    gesture.active = true
    engine.beginTransaction()
    const scroller = scrollerRef.current
    const captureElement = scroller ?? document.body
    try {
      captureElement.setPointerCapture(gesture.pointerId)
      this.capture = { element: captureElement, pointerId: gesture.pointerId }
    } catch (error) {
      if (!(error instanceof DOMException)) throw error
    }
    this.previousBodyUserSelect = document.body.style.userSelect
    document.body.style.userSelect = 'none'
    if (gesture.duplicateOnDrag && !gesture.duplicated) {
      const plan = planDuplicateClipsToNewTracks(engine.project, gesture.ids)
      if (plan) {
        for (const command of plan.commands) engine.dispatch(command)
        gesture.ids = plan.ids
        gesture.bases = collectClipDragBases(engine.project, plan.ids)
        gesture.anchor = gesture.bases.get(plan.ids[0] ?? '') ?? gesture.anchor
        gesture.createdTrackIds = plan.createdTrackIds
        gesture.duplicated = true
        engine.select(plan.ids)
        gesture.ignore = new Set<string>(gesture.ids)
      }
    }
    gesture.targets = collectSnapTargets(engine.project, engine.playback.state.currentTimeMs, gesture.ignore)
    gesture.scrollerRect = scroller?.getBoundingClientRect() ?? null
    gesture.layer = scroller && isPreviewMode(gesture.mode) ? new ClipPreviewLayer(scroller) : null
    this.startAutoScroll(gesture)
  }

  private flush(): void {
    if (this.updateFrame === null) return
    cancelAnimationFrame(this.updateFrame)
    this.updateFrame = null
    this.update()
  }

  private finish(): void {
    const gesture = this.gesture
    if (!gesture) return
    if (gesture.active) this.flush()
    this.gesture = null
    this.detach()
    if (!gesture.active) return
    const { engine, setSnapGuideMs } = this.deps
    setSnapGuideMs(null)
    const { pxPerMs, autoCrossfade } = this.deps.prefs()
    const pushedIntoNeighbour = autoCrossfade && gesture.mode === 'move' && gesture.ids.length === 1 && gesture.plan?.valid === false
    const plan = pushedIntoNeighbour ? gesture.lastValidPlan : gesture.plan
    if (isPreviewMode(gesture.mode)) {
      gesture.layer?.release(engine.project, pxPerMs)
      if (!plan || !this.commit(plan)) {
        engine.cancelTransaction()
        if (gesture.plan) gesture.layer?.settle(gesture.plan.previews, () => engine.project, pxPerMs, false)
        return
      }
    }
    removeEmptyCreatedTracks(engine, gesture.createdTrackIds)
    this.maybeAutoCrossfade(gesture)
    const touchesCollage =
      (gesture.mode === 'trim-start' || gesture.mode === 'trim-end') && gesture.ids.some((id) => getElementLocation(engine.project, id)?.element.groupId)
    if (touchesCollage) {
      try {
        retimeSequentialCollage(engine)
      } catch (error) {
        rethrowUnlessRejected(error)
      }
    }
    engine.endTransaction()
    if (gesture.plan) gesture.layer?.settle(gesture.plan.previews, () => engine.project, pxPerMs, true)
  }

  private commit(plan: DragPlan): boolean {
    if (!plan.valid) return false
    try {
      for (const command of plan.commands) this.deps.engine.dispatch(command)
      return true
    } catch (error) {
      rethrowUnlessRejected(error)
      return false
    }
  }

  private maybeAutoCrossfade(gesture: ClipDragGesture): void {
    const { engine } = this.deps
    const { pxPerMs, autoCrossfade } = this.deps.prefs()
    const anchorId = gesture.ids[0]
    if (!autoCrossfade || gesture.mode !== 'move' || gesture.ids.length !== 1 || anchorId === undefined) return
    const scrollDx = (this.deps.scrollerRef.current?.scrollLeft ?? gesture.startScrollLeft) - gesture.startScrollLeft
    const desiredStartMs = gesture.anchor.startMs + (gesture.lastClientX - gesture.startClientX + scrollDx) / pxPerMs
    const command = planAutoCrossfade(engine.project, { elementId: anchorId, desiredStartMs })
    if (!command) return
    try {
      engine.dispatch(command)
    } catch (error) {
      rethrowUnlessRejected(error)
    }
  }

  private cancel(): void {
    const gesture = this.gesture
    if (!gesture) return
    this.gesture = null
    this.detach()
    if (!gesture.active) return
    const { engine } = this.deps
    gesture.layer?.release(engine.project, this.deps.prefs().pxPerMs)
    engine.cancelTransaction()
    this.deps.setSnapGuideMs(null)
    if (gesture.plan) gesture.layer?.settle(gesture.plan.previews, () => engine.project, this.deps.prefs().pxPerMs, false)
  }

  private startAutoScroll(gesture: ClipDragGesture): void {
    const scroller = this.deps.scrollerRef.current
    const rect = gesture.scrollerRect
    if (!scroller || !rect) return
    this.autoScroll.start({
      scroller,
      bounds: { left: rect.left + this.deps.timelineHeaderPx(), right: rect.right, top: rect.top + RULER_HEIGHT, bottom: rect.bottom },
      pointer: () => (this.gesture === gesture && gesture.active ? { x: gesture.lastClientX, y: gesture.lastClientY } : null),
      axes: { x: true, y: true },
      onScroll: () => this.update(),
    })
  }

  private update(): void {
    const gesture = this.gesture
    if (!gesture?.active) return
    const { engine, setSnapGuideMs } = this.deps
    const { pxPerMs, snapEnabled } = this.deps.prefs()
    const scroller = this.deps.scrollerRef.current
    const scrollDx = (scroller?.scrollLeft ?? gesture.startScrollLeft) - gesture.startScrollLeft
    const deltaRawMs = (gesture.lastClientX - gesture.startClientX + scrollDx) / pxPerMs
    const thresholdMs = SNAP_PX / pxPerMs
    const snapping = snapEnabled && !(gesture.lastAltKey && !gesture.duplicated)

    if (isPreviewMode(gesture.mode)) {
      const rect = gesture.scrollerRect
      const pointerRow =
        scroller && rect ? Math.floor((gesture.lastClientY - rect.top + scroller.scrollTop - RULER_HEIGHT - NEW_TRACK_LANE_HEIGHT) / TRACK_HEIGHT) : null
      const plan = planClipDrag({
        project: engine.project,
        mode: gesture.mode,
        ids: gesture.ids,
        bases: gesture.bases,
        ignore: gesture.ignore,
        targets: gesture.targets,
        deltaRawMs,
        snapping,
        thresholdMs,
        pointerRow,
        newTrackId: gesture.createdTrackIds.length === 0 ? gesture.newTrackId : null,
      })
      gesture.plan = plan
      if (plan.valid) gesture.lastValidPlan = plan
      gesture.layer?.render(plan, gesture.bases, engine.project, pxPerMs)
      setSnapGuideMs(plan.guideMs)
      return
    }

    try {
      setSnapGuideMs(stepLiveGesture(engine, gesture.mode, gesture, { deltaRawMs, snapping, thresholdMs }))
    } catch (error) {
      rethrowUnlessRejected(error)
    }
  }
}

const ClipDragContext = createContext<ClipDragController | null>(null)

export const ClipDragProvider = ClipDragContext.Provider

export function useClipDragController(): ClipDragController {
  const engine = useEditor()
  const { setSnapGuideMs, timelineScrollRef, timelineHeaderPx } = useEditorUI()
  const latestHeaderPx = useLatest(timelineHeaderPx)
  return useDisposable(
    () =>
      new ClipDragController({
        engine,
        prefs: getEditorPrefs,
        timelineHeaderPx: () => latestHeaderPx.current,
        setSnapGuideMs,
        scrollerRef: timelineScrollRef,
      }),
  )
}

export function useClipDrag(): ClipDragController {
  const controller = useContext(ClipDragContext)
  if (!controller) throw new Error('useClipDrag must be used inside <ClipDragProvider>')
  return controller
}

import { canPlaceIgnoring, type ClipDragBase, type ClipDragMode } from '@mcut/editor'
import { getElementLocation, MIN_ELEMENT_DURATION_MS, type BuiltinCommand, type ElementId, type Project, type TrackId } from '@mcut/timeline'
import { snapClip, snapTime, type SnapTarget } from './timeline-snap'

export const NEW_TRACK_ABOVE_ROW = -1

export interface ClipPreview {
  id: ElementId
  startMs: number
  durationMs: number
  row: number
}

type DropTarget = { kind: 'lane'; trackId: TrackId } | { kind: 'new-track' } | null

export interface DragPlan {
  previews: ClipPreview[]
  commands: BuiltinCommand[]
  target: DropTarget
  valid: boolean
  guideMs: number | null
}

export type PreviewMode = Extract<ClipDragMode, 'move' | 'trim-start' | 'trim-end'>

interface PlanInput {
  project: Project
  mode: PreviewMode
  ids: readonly ElementId[]
  bases: ReadonlyMap<ElementId, ClipDragBase>
  ignore: ReadonlySet<string>
  targets: readonly SnapTarget[]
  deltaRawMs: number
  snapping: boolean
  thresholdMs: number
  pointerRow: number | null
  newTrackId: TrackId | null
}

export function visualRow(project: Project, trackIndex: number): number {
  return project.tracks.length - 1 - trackIndex
}

function mustBase(bases: ReadonlyMap<ElementId, ClipDragBase>, id: ElementId): ClipDragBase {
  const base = bases.get(id)
  if (!base) throw new Error(`no drag base for ${id}`)
  return base
}

function preview(
  project: Project,
  id: ElementId,
  base: ClipDragBase,
  startMs: number,
  durationMs: number,
  row = visualRow(project, base.trackIndex),
): ClipPreview {
  return { id, startMs, durationMs, row }
}

function planMove(input: PlanInput): DragPlan {
  const { project, ids, bases, ignore, targets, deltaRawMs, snapping, thresholdMs, pointerRow, newTrackId } = input
  const anchorId = ids[0]
  if (anchorId === undefined) return { previews: [], commands: [], target: null, valid: false, guideMs: null }
  const anchor = mustBase(bases, anchorId)
  const snapped = snapClip(anchor.startMs + deltaRawMs, anchor.durationMs, targets, thresholdMs, { enabled: snapping, fps: project.fps })
  const minStart = Math.min(...ids.map((id) => mustBase(bases, id).startMs))
  const deltaMs = Math.max(Math.round(snapped.ms - anchor.startMs), -minStart)

  if (ids.length > 1) {
    const moves = ids.map((id) => {
      const base = mustBase(bases, id)
      return { id, base, startMs: base.startMs + deltaMs, track: project.tracks[base.trackIndex] }
    })
    const valid = moves.every(
      ({ base, startMs, track }) => track && !track.locked && (track.magnetic || canPlaceIgnoring(track, startMs, base.durationMs, ignore)),
    )
    return {
      previews: moves.map(({ id, base, startMs }) => preview(project, id, base, startMs, base.durationMs)),
      commands: deltaMs === 0 ? [] : moves.map(({ id, startMs }) => ({ type: 'moveElement', elementId: id, startMs })),
      target: null,
      valid,
      guideMs: valid ? snapped.guideMs : null,
    }
  }

  const trackCount = project.tracks.length
  const targetIndex = pointerRow === null ? anchor.trackIndex : trackCount - 1 - pointerRow
  const startMs = anchor.startMs + deltaMs
  if ((targetIndex >= trackCount || targetIndex < 0) && newTrackId !== null) {
    const above = targetIndex >= trackCount
    return {
      previews: [preview(project, anchorId, anchor, startMs, anchor.durationMs, above ? NEW_TRACK_ABOVE_ROW : trackCount)],
      commands: [
        { type: 'addTrack', id: newTrackId, ...(above ? {} : { index: 0 }) },
        { type: 'moveElement', elementId: anchorId, startMs, toTrackId: newTrackId },
      ],
      target: above ? { kind: 'new-track' } : null,
      valid: true,
      guideMs: snapped.guideMs,
    }
  }

  const clampedIndex = Math.max(0, Math.min(targetIndex, trackCount - 1))
  const track = project.tracks[clampedIndex]
  if (!track) return { previews: [], commands: [], target: null, valid: false, guideMs: null }
  const row = visualRow(project, clampedIndex)
  const magneticStartMs = Math.max(0, Math.round(anchor.startMs + deltaRawMs))
  const landingMs = track.magnetic ? magneticStartMs : startMs
  const valid = !track.locked && (track.magnetic || canPlaceIgnoring(track, landingMs, anchor.durationMs, ignore))
  const unchanged = clampedIndex === anchor.trackIndex && landingMs === anchor.startMs
  return {
    previews: [preview(project, anchorId, anchor, landingMs, anchor.durationMs, row)],
    commands: unchanged ? [] : [{ type: 'moveElement', elementId: anchorId, startMs: landingMs, toTrackId: track.id }],
    target: { kind: 'lane', trackId: track.id },
    valid,
    guideMs: valid && !track.magnetic ? snapped.guideMs : null,
  }
}

interface TrimMember {
  id: ElementId
  base: ClipDragBase
  assetDurationMs: number | undefined
}

function trimMembers(project: Project, ids: readonly ElementId[], bases: ReadonlyMap<ElementId, ClipDragBase>): TrimMember[] {
  return ids.flatMap((id) => {
    const base = bases.get(id)
    const element = getElementLocation(project, id)?.element
    if (!base || !element) return []
    const asset = 'assetId' in element ? project.assets[element.assetId] : undefined
    return [{ id, base, assetDurationMs: asset?.durationMs }]
  })
}

function planTrim(input: PlanInput, edge: 'start' | 'end'): DragPlan {
  const { project, ids, bases, ignore, targets, deltaRawMs, snapping, thresholdMs } = input
  const anchorId = ids[0]
  if (anchorId === undefined) return { previews: [], commands: [], target: null, valid: false, guideMs: null }
  const anchor = mustBase(bases, anchorId)
  const members = trimMembers(project, ids, bases)
  const edgeMs = edge === 'end' ? anchor.startMs + anchor.durationMs : anchor.startMs
  const snapped = snapTime(edgeMs + deltaRawMs, targets, thresholdMs, { enabled: snapping, fps: project.fps })
  const wanted = Math.round(snapped.ms) - edgeMs
  let deltaMs = wanted
  for (const { base, assetDurationMs } of members) {
    if (edge === 'end') {
      if (!base.hasTimeMap && assetDurationMs !== undefined && base.trimStartMs !== undefined) {
        deltaMs = Math.min(deltaMs, base.reversed ? base.trimStartMs : assetDurationMs - base.trimStartMs - base.durationMs)
      }
      deltaMs = Math.max(deltaMs, MIN_ELEMENT_DURATION_MS - base.durationMs)
      continue
    }
    deltaMs = Math.max(deltaMs, -base.startMs)
    if (!base.hasTimeMap && base.trimStartMs !== undefined) {
      deltaMs = Math.max(deltaMs, base.reversed && assetDurationMs !== undefined ? -(assetDurationMs - base.trimStartMs - base.durationMs) : -base.trimStartMs)
    }
    if (base.hasTimeMap && base.reversed) deltaMs = Math.max(deltaMs, 0)
    deltaMs = Math.min(deltaMs, base.durationMs - MIN_ELEMENT_DURATION_MS)
  }
  const shaped = members.map(({ id, base }) => ({
    id,
    base,
    startMs: edge === 'end' ? base.startMs : base.startMs + deltaMs,
    durationMs: edge === 'end' ? base.durationMs + deltaMs : base.durationMs - deltaMs,
  }))
  const valid = shaped.every(({ base, startMs, durationMs }) => {
    const track = project.tracks[base.trackIndex]
    return track !== undefined && !track.locked && canPlaceIgnoring(track, startMs, durationMs, ignore)
  })
  return {
    previews: shaped.map(({ id, base, startMs, durationMs }) => preview(project, id, base, startMs, durationMs)),
    commands: deltaMs === 0 ? [] : shaped.map(({ id }) => ({ type: 'trimEdge', elementId: id, edge, deltaMs })),
    target: null,
    valid,
    guideMs: valid && deltaMs === wanted ? snapped.guideMs : null,
  }
}

export function isPreviewMode(mode: ClipDragMode): mode is PreviewMode {
  return mode === 'move' || mode === 'trim-start' || mode === 'trim-end'
}

export function planClipDrag(input: PlanInput): DragPlan {
  switch (input.mode) {
    case 'move':
      return planMove(input)
    case 'trim-start':
      return planTrim(input, 'start')
    case 'trim-end':
      return planTrim(input, 'end')
    default: {
      const exhaustive: never = input.mode
      return exhaustive
    }
  }
}

import { type ClipDragBase } from '@mcut/editor'
import { getElementLocation, type ElementId, type Project } from '@mcut/timeline'
import { NEW_TRACK_ABOVE_ROW, visualRow, type ClipPreview, type DragPlan } from './timeline-drag-plan'

export const TRACK_HEIGHT = 56
export const RULER_HEIGHT = 28
export const NEW_TRACK_LANE_HEIGHT = 36

const SETTLE_MS = 180
const RETURN_MS = 240
export const ROW_SHIFT_MS = 150

type EaseToken = '--ease-out' | '--ease-in-out'

export function motionEase(token: EaseToken): string {
  const value = getComputedStyle(document.documentElement).getPropertyValue(token).trim()
  return value === '' ? 'ease-out' : value
}

function prefersReducedMotion(): boolean {
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches
}

function rowCenterPx(row: number): number {
  return row === NEW_TRACK_ABOVE_ROW ? -NEW_TRACK_LANE_HEIGHT / 2 : row * TRACK_HEIGHT + TRACK_HEIGHT / 2
}

interface Glide {
  x: number
  y: number
  width?: { from: number; to: number }
}

export function glide(node: HTMLElement, from: Glide, durationMs: number, token: EaseToken): void {
  if (Math.abs(from.x) < 0.5 && Math.abs(from.y) < 0.5 && from.width === undefined) return
  if (prefersReducedMotion()) return
  const width = from.width
  node.setAttribute('data-settling', '')
  const animation = node.animate(
    [
      { translate: `${from.x}px ${from.y}px`, ...(width ? { width: `${width.from}px` } : {}) },
      { translate: '0px 0px', ...(width ? { width: `${width.to}px` } : {}) },
    ],
    { duration: durationMs, easing: motionEase(token) },
  )
  const lower = () => node.removeAttribute('data-settling')
  animation.addEventListener('finish', lower)
  animation.addEventListener('cancel', lower)
}

function clipWidthPx(durationMs: number, pxPerMs: number): number {
  return Math.max(10, durationMs * pxPerMs)
}

export class ClipPreviewLayer {
  private readonly nodes = new Map<ElementId, HTMLElement>()
  private highlighted: HTMLElement | null = null

  constructor(private readonly root: HTMLElement) {}

  private find(selector: string): HTMLElement | null {
    return this.root.querySelector<HTMLElement>(selector)
  }

  private clipNode(id: ElementId): HTMLElement | null {
    const known = this.nodes.get(id)
    if (known?.isConnected) return known
    const node = this.find(`[data-mcut-element-id="${CSS.escape(id)}"]`)
    if (!node) return null
    this.nodes.set(id, node)
    node.setAttribute('data-dragging', '')
    return node
  }

  render(plan: DragPlan, bases: ReadonlyMap<ElementId, ClipDragBase>, project: Project, pxPerMs: number): void {
    for (const preview of plan.previews) {
      const base = bases.get(preview.id)
      const node = this.clipNode(preview.id)
      if (!base || !node) continue
      const dx = (preview.startMs - base.startMs) * pxPerMs
      const dy = rowCenterPx(preview.row) - rowCenterPx(visualRow(project, base.trackIndex))
      node.style.translate = `${dx}px ${dy}px`
      node.style.width = `${clipWidthPx(preview.durationMs, pxPerMs)}px`
      node.toggleAttribute('data-drop-invalid', !plan.valid)
    }
    const target = plan.target
    const lane =
      target === null ? null : this.find(target.kind === 'new-track' ? '[data-mcut-new-track-lane]' : `[data-mcut-lane="${CSS.escape(target.trackId)}"]`)
    if (lane !== this.highlighted) this.highlighted?.removeAttribute('data-drop-target')
    this.highlighted = lane
    lane?.setAttribute('data-drop-target', plan.valid ? 'valid' : 'invalid')
  }

  release(project: Project, pxPerMs: number): void {
    for (const [id, node] of this.nodes) {
      const element = getElementLocation(project, id)?.element
      node.style.translate = ''
      if (element) node.style.width = `${clipWidthPx(element.durationMs, pxPerMs)}px`
      node.removeAttribute('data-dragging')
      node.removeAttribute('data-drop-invalid')
    }
    this.nodes.clear()
    this.highlighted?.removeAttribute('data-drop-target')
    this.highlighted = null
  }

  settle(previews: readonly ClipPreview[], project: () => Project, pxPerMs: number, landed: boolean): void {
    if (previews.length === 0) return
    requestAnimationFrame(() => {
      const after = project()
      for (const preview of previews) {
        const location = getElementLocation(after, preview.id)
        const node = this.find(`[data-mcut-element-id="${CSS.escape(preview.id)}"]`)
        if (!location || !node) continue
        const { element } = location
        glide(
          node,
          {
            x: (preview.startMs - element.startMs) * pxPerMs,
            y: rowCenterPx(preview.row) - rowCenterPx(visualRow(after, location.trackIndex)),
            ...(preview.durationMs === element.durationMs
              ? {}
              : { width: { from: clipWidthPx(preview.durationMs, pxPerMs), to: clipWidthPx(element.durationMs, pxPerMs) } }),
          },
          landed ? SETTLE_MS : RETURN_MS,
          landed ? '--ease-out' : '--ease-in-out',
        )
      }
    })
  }
}

import { type ClipDragBase, type ClipDragMode } from '@mcut/editor'
import { CommandError, getElementLocation, type EditorEngine, type ElementId, type TrackId } from '@mcut/timeline'
import { snapClip, snapTime, type SnapTarget } from './timeline-snap'

export type LiveMode = Exclude<ClipDragMode, 'move' | 'trim-start' | 'trim-end'>

interface LiveGesture {
  ids: readonly ElementId[]
  anchor: ClipDragBase
  targets: readonly SnapTarget[]
  appliedDeltaMs: number
  rollTargetId: ElementId | null
  slipRange: { minMs: number; maxMs: number } | null
}

interface LiveStepInput {
  deltaRawMs: number
  snapping: boolean
  thresholdMs: number
}

export function rethrowUnlessRejected(error: unknown): void {
  if (!(error instanceof CommandError)) throw error
}

export function removeEmptyCreatedTracks(engine: EditorEngine, trackIds: readonly TrackId[]) {
  for (const trackId of trackIds) {
    const track = engine.project.tracks.find((t) => t.id === trackId)
    if (track && track.elements.length === 0) {
      engine.dispatch({ type: 'removeTrack', trackId })
    }
  }
}

function slipDeltaOpposingThePointer(pointerDeltaMs: number): number {
  return -Math.round(pointerDeltaMs)
}

export function stepLiveGesture(
  engine: EditorEngine,
  mode: LiveMode,
  gesture: LiveGesture,
  { deltaRawMs, snapping, thresholdMs }: LiveStepInput,
): number | null {
  const project = engine.project
  const { anchor, targets } = gesture
  const anchorId = gesture.ids[0]
  if (anchorId === undefined) return null
  const snapOptions = { enabled: snapping, fps: project.fps }
  const apply = (wanted: number, dispatch: (stepMs: number) => void) => {
    const stepMs = wanted - gesture.appliedDeltaMs
    if (stepMs !== 0) {
      dispatch(stepMs)
      gesture.appliedDeltaMs = wanted
    }
  }

  switch (mode) {
    case 'slip': {
      const range = gesture.slipRange ?? { minMs: -Infinity, maxMs: Infinity }
      const wanted = Math.max(range.minMs, Math.min(range.maxMs, slipDeltaOpposingThePointer(deltaRawMs)))
      apply(wanted, (stepMs) => {
        for (const id of gesture.ids) {
          const element = getElementLocation(project, id)?.element
          if (!element) continue
          if (element.type !== 'video' && element.type !== 'audio' && element.type !== 'multicam') continue
          engine.dispatch({ type: 'slipElement', elementId: id, deltaMs: stepMs })
        }
      })
      return null
    }
    case 'slide': {
      const snapped = snapClip(anchor.startMs + deltaRawMs, anchor.durationMs, targets, thresholdMs, snapOptions)
      const wanted = Math.round(snapped.ms) - anchor.startMs
      apply(wanted, (stepMs) => engine.dispatch({ type: 'slideElement', elementId: anchorId, deltaMs: stepMs }))
      return gesture.appliedDeltaMs === wanted ? snapped.guideMs : null
    }
    case 'roll-start':
    case 'roll-end': {
      const cutBaseMs = mode === 'roll-end' ? anchor.startMs + anchor.durationMs : anchor.startMs
      const snapped = snapTime(cutBaseMs + deltaRawMs, targets, thresholdMs, snapOptions)
      const wanted = Math.round(snapped.ms) - cutBaseMs
      const rollId = mode === 'roll-end' ? anchorId : gesture.rollTargetId
      if (!rollId) return null
      apply(wanted, (stepMs) => engine.dispatch({ type: 'rollEdit', elementId: rollId, deltaMs: stepMs }))
      return gesture.appliedDeltaMs === wanted ? snapped.guideMs : null
    }
    case 'ripple-start':
    case 'ripple-end': {
      const edge = mode === 'ripple-end' ? 'end' : 'start'
      const edgeBaseMs = edge === 'end' ? anchor.startMs + anchor.durationMs : anchor.startMs
      const rippleTargets = targets.filter((t) => t.kind === 'marker' || t.kind === 'playhead' || t.kind === 'origin')
      const snapped = snapTime(edgeBaseMs + deltaRawMs, rippleTargets, thresholdMs, snapOptions)
      const wanted = Math.round(snapped.ms) - edgeBaseMs
      apply(wanted, (stepMs) => engine.dispatch({ type: 'rippleTrim', elementId: anchorId, edge, deltaMs: stepMs }))
      return gesture.appliedDeltaMs === wanted ? snapped.guideMs : null
    }
    default: {
      const exhaustive: never = mode
      return exhaustive
    }
  }
}

const EDGE_PX = 36
const MAX_STEP_PX = 18

function edgeSpeed(pos: number, min: number, max: number): number {
  if (pos < min + EDGE_PX) return -Math.min(MAX_STEP_PX, ((min + EDGE_PX - pos) / EDGE_PX) * MAX_STEP_PX)
  if (pos > max - EDGE_PX) return Math.min(MAX_STEP_PX, ((pos - (max - EDGE_PX)) / EDGE_PX) * MAX_STEP_PX)
  return 0
}

interface AutoScrollBounds {
  left: number
  right: number
  top: number
  bottom: number
}

interface AutoScrollSource {
  scroller: HTMLElement
  bounds: AutoScrollBounds
  pointer: () => { x: number; y: number } | null
  axes: { x: boolean; y: boolean }
  onScroll: () => void
}

function stepAxis(scroller: HTMLElement, axis: 'scrollLeft' | 'scrollTop', delta: number, max: number): boolean {
  if (delta === 0) return false
  const next = Math.max(0, Math.min(scroller[axis] + delta, max))
  if (next === scroller[axis]) return false
  scroller[axis] = next
  return true
}

export class EdgeAutoScroll {
  private frame: number | null = null

  start(source: AutoScrollSource): void {
    this.stop()
    const { scroller, bounds, axes } = source
    const tick = () => {
      const pointer = source.pointer()
      if (pointer === null) {
        this.frame = null
        return
      }
      const dx = axes.x ? edgeSpeed(pointer.x, bounds.left, bounds.right) : 0
      const dy = axes.y ? edgeSpeed(pointer.y, bounds.top, bounds.bottom) : 0
      const scrolledX = stepAxis(scroller, 'scrollLeft', dx, scroller.scrollWidth - scroller.clientWidth)
      const scrolledY = stepAxis(scroller, 'scrollTop', dy, scroller.scrollHeight - scroller.clientHeight)
      if (scrolledX || scrolledY) source.onScroll()
      this.frame = requestAnimationFrame(tick)
    }
    this.frame = requestAnimationFrame(tick)
  }

  stop(): void {
    if (this.frame === null) return
    cancelAnimationFrame(this.frame)
    this.frame = null
  }
}

'use client'

import { createContext, useContext } from 'react'
import { useDisposable, useEditor } from '@mcut/react'
import { type EditorEngine, type TrackId } from '@mcut/timeline'
import { useEditorUI } from './editor-ui'
import { EdgeAutoScroll } from './timeline-autoscroll'
import { rethrowUnlessRejected } from './timeline-drag-live'
import { glide, motionEase, ROW_SHIFT_MS, RULER_HEIGHT, TRACK_HEIGHT } from './timeline-drag-preview'

const DRAG_THRESHOLD_PX = 4
const SETTLE_MS = 180

interface TrackGesture {
  trackId: TrackId
  pointerId: number
  fromRow: number
  targetRow: number
  startClientY: number
  startScrollTop: number
  lastClientY: number
  active: boolean
  rows: HTMLElement[]
  capture: Element
}

function reorderCommand(engine: EditorEngine, trackId: TrackId, targetRow: number) {
  return { type: 'reorderTrack' as const, trackId, toIndex: engine.project.tracks.length - 1 - targetRow }
}

export class TrackDragController {
  private gesture: TrackGesture | null = null
  private frame: number | null = null
  private listening: AbortController | null = null
  private transitionReset: ReturnType<typeof setTimeout> | null = null
  private readonly autoScroll = new EdgeAutoScroll()

  constructor(
    private readonly engine: EditorEngine,
    private readonly scrollerRef: React.RefObject<HTMLElement | null>,
  ) {}

  begin(event: { clientY: number; pointerId: number; currentTarget: Element }, trackId: TrackId): void {
    this.cancel()
    const fromRow = this.visualRow(trackId)
    if (fromRow === -1) return
    this.gesture = {
      trackId,
      pointerId: event.pointerId,
      fromRow,
      targetRow: fromRow,
      startClientY: event.clientY,
      startScrollTop: this.scrollerRef.current?.scrollTop ?? 0,
      lastClientY: event.clientY,
      active: false,
      rows: [],
      capture: event.currentTarget,
    }
    this.listening = new AbortController()
    const { signal } = this.listening
    window.addEventListener('pointermove', this.onPointerMove, { signal })
    window.addEventListener('pointerup', this.onPointerUp, { signal })
    window.addEventListener('pointercancel', this.onPointerCancel, { signal })
    window.addEventListener('keydown', this.onKeyDown, { signal, capture: true })
    window.addEventListener('blur', () => this.finish(false), { signal })
  }

  nudge(trackId: TrackId, rows: -1 | 1): void {
    const row = this.visualRow(trackId)
    const targetRow = row + rows
    if (row === -1 || targetRow < 0 || targetRow >= this.engine.project.tracks.length) return
    if (!this.dispatch(trackId, targetRow)) return
    requestAnimationFrame(() => {
      this.scrollerRef.current?.querySelector<HTMLElement>(`[data-mcut-track-grip="${CSS.escape(trackId)}"]`)?.focus()
    })
  }

  dispose(): void {
    this.cancel()
    this.clearTransitionReset()
  }

  private clearTransitionReset(): void {
    if (this.transitionReset === null) return
    clearTimeout(this.transitionReset)
    this.transitionReset = null
  }

  private visualRow(trackId: TrackId): number {
    const index = this.engine.project.tracks.findIndex((track) => track.id === trackId)
    return index === -1 ? -1 : this.engine.project.tracks.length - 1 - index
  }

  private dispatch(trackId: TrackId, targetRow: number): boolean {
    try {
      this.engine.dispatch(reorderCommand(this.engine, trackId, targetRow))
      return true
    } catch (error) {
      rethrowUnlessRejected(error)
      return false
    }
  }

  private onPointerMove = (event: PointerEvent) => {
    const gesture = this.gesture
    if (!gesture || event.pointerId !== gesture.pointerId) return
    if ((event.buttons & 1) === 0) {
      this.finish(true)
      return
    }
    gesture.lastClientY = event.clientY
    if (!gesture.active) {
      if (Math.abs(event.clientY - gesture.startClientY) < DRAG_THRESHOLD_PX) return
      this.activate(gesture)
    }
    if (this.frame !== null) return
    this.frame = requestAnimationFrame(() => {
      this.frame = null
      this.update()
    })
  }

  private onPointerUp = (event: PointerEvent) => {
    if (this.gesture?.pointerId === event.pointerId) this.finish(true)
  }

  private onPointerCancel = (event: PointerEvent) => {
    if (this.gesture?.pointerId === event.pointerId) this.finish(false)
  }

  private onKeyDown = (event: KeyboardEvent) => {
    if (event.key !== 'Escape' || !this.gesture) return
    event.preventDefault()
    event.stopPropagation()
    this.finish(false)
  }

  private activate(gesture: TrackGesture): void {
    const scroller = this.scrollerRef.current
    gesture.active = true
    this.clearTransitionReset()
    gesture.rows = scroller ? [...scroller.querySelectorAll<HTMLElement>('[data-mcut-track-row]')] : []
    const shift = `translate ${ROW_SHIFT_MS}ms ${motionEase('--ease-out')}`
    for (const [row, node] of gesture.rows.entries()) {
      node.style.transition = row === gesture.fromRow ? '' : shift
      node.toggleAttribute('data-dragging', row === gesture.fromRow)
    }
    try {
      gesture.capture.setPointerCapture(gesture.pointerId)
    } catch (error) {
      if (!(error instanceof DOMException)) throw error
    }
    if (!scroller) return
    const rect = scroller.getBoundingClientRect()
    this.autoScroll.start({
      scroller,
      bounds: { left: rect.left, right: rect.right, top: rect.top + RULER_HEIGHT, bottom: rect.bottom },
      pointer: () => (this.gesture === gesture ? { x: rect.left + rect.width / 2, y: gesture.lastClientY } : null),
      axes: { x: false, y: true },
      onScroll: () => this.update(),
    })
  }

  private offsetPx(gesture: TrackGesture): number {
    const scrollDy = (this.scrollerRef.current?.scrollTop ?? gesture.startScrollTop) - gesture.startScrollTop
    const raw = gesture.lastClientY - gesture.startClientY + scrollDy
    const last = gesture.rows.length - 1
    return Math.max(-gesture.fromRow * TRACK_HEIGHT, Math.min((last - gesture.fromRow) * TRACK_HEIGHT, raw))
  }

  private update(): void {
    const gesture = this.gesture
    if (!gesture?.active) return
    const offset = this.offsetPx(gesture)
    const targetRow = Math.round(gesture.fromRow + offset / TRACK_HEIGHT)
    gesture.rows[gesture.fromRow]?.style.setProperty('translate', `0px ${offset}px`)
    if (targetRow === gesture.targetRow) return
    gesture.targetRow = targetRow
    for (const [row, node] of gesture.rows.entries()) {
      if (row === gesture.fromRow) continue
      const shift =
        gesture.fromRow < targetRow && row > gesture.fromRow && row <= targetRow
          ? -1
          : gesture.fromRow > targetRow && row >= targetRow && row < gesture.fromRow
            ? 1
            : 0
      node.style.translate = shift === 0 ? '' : `0px ${shift * TRACK_HEIGHT}px`
    }
  }

  private finish(commit: boolean): void {
    const gesture = this.gesture
    if (!gesture) return
    if (gesture.active && this.frame !== null) this.update()
    this.cancel()
    if (!gesture.active) return
    const offset = this.offsetPx(gesture)
    const moved = commit && gesture.targetRow !== gesture.fromRow && this.dispatch(gesture.trackId, gesture.targetRow)
    const dragged = gesture.rows[gesture.fromRow]
    for (const node of gesture.rows) {
      if (node === dragged) continue
      if (moved) node.style.transition = ''
      node.style.translate = ''
    }
    if (dragged) {
      dragged.style.translate = ''
      dragged.removeAttribute('data-dragging')
    }
    if (!moved) {
      this.transitionReset = setTimeout(() => {
        this.transitionReset = null
        for (const node of gesture.rows) node.style.transition = ''
      }, ROW_SHIFT_MS)
    }
    requestAnimationFrame(() => {
      if (!dragged) return
      const landedRow = moved ? gesture.targetRow : gesture.fromRow
      glide(dragged, { x: 0, y: gesture.fromRow * TRACK_HEIGHT + offset - landedRow * TRACK_HEIGHT }, SETTLE_MS, moved ? '--ease-out' : '--ease-in-out')
    })
  }

  private cancel(): void {
    const gesture = this.gesture
    this.gesture = null
    this.listening?.abort()
    this.listening = null
    this.autoScroll.stop()
    if (this.frame !== null) {
      cancelAnimationFrame(this.frame)
      this.frame = null
    }
    if (gesture?.capture.hasPointerCapture(gesture.pointerId)) gesture.capture.releasePointerCapture(gesture.pointerId)
  }
}

const TrackDragContext = createContext<TrackDragController | null>(null)

export const TrackDragProvider = TrackDragContext.Provider

export function useTrackDragController(): TrackDragController {
  const engine = useEditor()
  const { timelineScrollRef } = useEditorUI()
  return useDisposable(() => new TrackDragController(engine, timelineScrollRef))
}

export function useTrackDrag(): TrackDragController {
  const controller = useContext(TrackDragContext)
  if (!controller) throw new Error('useTrackDrag must be used inside <TrackDragProvider>')
  return controller
}

export function formatTimecode(ms: number): string {
  const total = Math.max(0, ms)
  const minutes = Math.floor(total / 60_000)
  const seconds = Math.floor((total % 60_000) / 1000)
  const tenths = Math.floor((total % 1000) / 100)
  return `${minutes}:${String(seconds).padStart(2, '0')}.${tenths}`
}

export function formatRulerLabel(ms: number): string {
  const minutes = Math.floor(ms / 60_000)
  const seconds = Math.round((ms % 60_000) / 1000)
  return `${minutes}:${String(seconds).padStart(2, '0')}`
}

export function formatDurationBadge(ms: number): string {
  return formatRulerLabel(Math.round(ms / 1000) * 1000)
}

